"use client";

import { useEffect, useRef } from "react";
import SplitText from "./SplitText";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import type { RefObject } from "react";

const TITLE = "TYPEWAVE";

/**
 * The cover. The wordmark is the instrument: each glyph of TYPEWAVE rises in
 * on load (char-split, aria-safe, 45ms stagger), then — under a fine pointer
 * and without reduced motion — the page's scroll velocity writes the glyphs'
 * scaleX. The faster you scroll, the more the letters stretch, exactly like
 * a waveform reacting to amplitude. Scroll velocity is read from the shared
 * ref (no React renders per frame) and written imperatively per glyph in a
 * single rAF, transform-only.
 *
 * The velocity stretch is gated behind `.typewave-js` and behind the velocity
 * hook's `enabled` flag, so under reduced motion (and on no-JS, and on touch
 * where the hero scrubs with the page) the wordmark rests at scaleX(1) — the
 * finished, readable state. The hero is never blank; the letters are always
 * there, fully styled, with or without motion.
 *
 * `velRef` is passed in from the page so the velocity signal is shared with
 * the section heads that also react to amplitude — one source of truth.
 */
export default function Hero({
  velRef,
}: {
  velRef: RefObject<number>;
}) {
  const heroRef = useRef<HTMLElement | null>(null);
  const reduced = usePrefersReducedMotion();

  // Arm the entrance animation (char rise). Without JS the class never lands
  // and the wordmark is simply complete and readable.
  useEffect(() => {
    heroRef.current?.classList.add("is-on");
  }, []);

  // Velocity → per-glyph scaleX stretch, transform-only, in a single rAF.
  // The glyphs are queried inside the effect (SplitText renders the spans as
  // aria-hidden visuals; the h1 carries the real accessible name).
  useEffect(() => {
    const hero = heroRef.current;
    if (!hero) return;
    if (reduced) return;
    // Only the hero reacts to velocity on fine pointers; on touch the page
    // scroll itself is the interaction and an extra stretch fights the scroll.
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }
    const glyphs = Array.from(
      hero.querySelectorAll<HTMLSpanElement>(
        ".typewave-hero__title .typewave-split__ch",
      ),
    );
    if (glyphs.length === 0) return;

    let raf = 0;
    const VEL_GAIN = 0.42; // max added stretch per unit velocity (amplitude)
    const DECAY_PER_FRAME = 0.16; // how fast the visual stretch releases

    let shown = 0; // the displayed amplitude (lerped), 0 at rest
    const stretch = () => {
      raf = 0;
      const target = Math.min(velRef.current, 1);
      // approach while scrolling, decay while at rest
      if (target > shown) shown += (target - shown) * 0.35;
      else shown *= 1 - DECAY_PER_FRAME;
      if (shown < 0.001) shown = 0;
      const amp = shown * VEL_GAIN;
      // a small per-glyph phase so the stretch reads as a moving wave, not a
      // uniform bulge — alternating glyphs pull slightly opposite
      for (let i = 0; i < glyphs.length; i++) {
        const phase = (i % 2 === 0 ? 1 : -0.7) * amp;
        glyphs[i].style.transform = `scaleX(${(1 + phase).toFixed(4)})`;
      }
      if (shown > 0.0005) {
        raf = requestAnimationFrame(stretch);
      }
    };

    let armed = false;
    const arm = () => {
      if (armed) return;
      armed = true;
      if (!raf) raf = requestAnimationFrame(stretch);
    };
    // the velocity hook updates velRef on scroll; we just need to wake the
    // loop whenever the page scrolls and let it run until it settles.
    window.addEventListener("scroll", arm, { passive: true });
    return () => {
      window.removeEventListener("scroll", arm);
      if (raf) cancelAnimationFrame(raf);
      for (const g of glyphs) g.style.transform = "";
      armed = false;
      shown = 0;
    };
  }, [reduced, velRef]);

  return (
    <header
      ref={heroRef}
      className="typewave-hero"
      aria-labelledby="typewave-title"
    >
      {/* A generated waveform render deep behind the cover — the ambient
         sound-field the wordmark plays against. Pure-black base preserved;
         only thin acid lines bleed through, so the page stays Swiss/minimal. */}
      <img
        className="typewave-hero__field"
        src="/media/typewave/waveform.avif"
        alt=""
        aria-hidden="true"
        draggable="false"
      />

      <div className="typewave-frame typewave-hero__inner">
        <p className="typewave-hero__kicker typewave-mono">
          <span>typewave — type that plays like a track · 2026</span>
          <span lang="ko">타입웨이브 — 연주되는 타이포그래피</span>
        </p>

        <h1 className="typewave-hero__title" id="typewave-title" aria-label={TITLE}>
          <SplitText text={TITLE} />
        </h1>

        <p className="typewave-hero__ko" lang="ko">
          타입웨이브
        </p>

        <div className="typewave-hero__wave" aria-hidden="true">
          <span className="typewave-hero__zero typewave-mono">0.000s · 0dB</span>
          <i className="typewave-hero__line" />
        </div>

        <div className="typewave-hero__foot">
          <p className="typewave-hero__lede">
            An electronic artist whose only instrument is the typeface.
            Scroll, and the wordmark behaves like a waveform — stretched by
            velocity, scrubbed by hand, set to one acid accent on pure black.
            <span lang="ko">
              악기가 오직 타이포그래피뿐인 전자음악 아티스트. 스크롤하면 워드마크가
              파형처럼 움직인다 — 속도로 늘어나고, 손으로 스크럽되고, 완전한 검정
              위 산성 초록 하나로 세팅된다.
            </span>
          </p>
          <p className="typewave-hero__meta typewave-mono">
            <span>single · TYPEWAVE / 03:12</span>
            <span>variable font · wdth 62–125</span>
            <span lang="ko">스크롤이 재생입니다</span>
          </p>
        </div>

        <p className="typewave-hero__cue typewave-mono" aria-hidden="true">
          ↓ scroll to play · 스크롤 = 재생
        </p>
      </div>
    </header>
  );
}

"use client";

import { useEffect, useRef } from "react";
import SplitText from "./SplitText";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

const CLOSER = "PLAY IT AGAIN";

/**
 * The closer. A final giant kinetic wordmark — "PLAY IT AGAIN" — that
 * stretches across the viewport at full width (wdth 125, the widest the
 * axis goes) and reveals glyph-by-glyph on enter (char-split, aria-safe,
 * the same vocabulary as the hero, so the page opens and closes on the
 * same gesture). Below it, a real bilingual credit + legal footer: the
 * fictional label, the engineer's note, the type license, the MIT code
 * line.
 *
 * The wordmark rests at its widest (the morph's terminal state) and only
 * animates its entrance — the page ends on a held, resolved chord, not
 * another loop. Reduced motion / no-JS: the word is simply there, fully
 * styled, at its final width.
 */
export default function KineticFooter() {
  const footRef = useRef<HTMLElement | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const foot = footRef.current;
    if (!foot) return;
    // Reveal the closer wordmark when the footer enters.
    if (reduced || !("IntersectionObserver" in window)) {
      foot.classList.add("is-on");
      return;
    }
    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          if (hit.isIntersecting) {
            foot.classList.add("is-on");
            io.disconnect();
          }
        }
      },
      { threshold: 0.25 },
    );
    io.observe(foot);
    return () => io.disconnect();
  }, [reduced]);

  return (
    <footer
      ref={footRef}
      className="typewave-footer"
      aria-labelledby="typewave-closer"
    >
      <div className="typewave-frame typewave-footer__inner">
        <p className="typewave-footer__kicker typewave-mono">
          <span>side b · end of track</span>
          <span lang="ko">B면 · 트랙의 끝</span>
        </p>

        <h2
          className="typewave-footer__word"
          id="typewave-closer"
          aria-label={CLOSER}
        >
          <SplitText text={CLOSER} />
        </h2>
        <p className="typewave-footer__wordko" lang="ko">
          다시 재생
        </p>

        <div className="typewave-footer__cols">
          <section className="typewave-footer__block">
            <h3 className="typewave-footer__h">Label · 레이블</h3>
            <p>
              Released on ACID TYPE RECORDINGS — a fictional imprint for type
              that wants to be heard.
              <span lang="ko">
                ACID TYPE RECORDINGS에서 발매 — 들리고 싶은 타이포를 위한 가상의
                레이블.
              </span>
            </p>
          </section>
          <section className="typewave-footer__block">
            <h3 className="typewave-footer__h">Engineering · 엔지니어링</h3>
            <p>
              Built with one variable font, one accent, and zero dependencies.
              Every waveform on this page is a letter being moved.
              <span lang="ko">
                가변 폰트 하나, 액센트 하나, 의존성 없이. 이 페이지의 모든 파형은
                움직이는 글자다.
              </span>
            </p>
          </section>
          <section className="typewave-footer__block">
            <h3 className="typewave-footer__h">Type · 서체</h3>
            <p>
              Archivo (OFL), Black Han Sans (OFL), Noto Sans KR (OFL), Space
              Mono (OFL) via next/font. Korean is first-class, never a gloss.
              <span lang="ko">
                Archivo, Black Han Sans, Noto Sans KR, Space Mono — 모두 OFL.
                next/font로 불러옴. 한국어는 번역이 아니라 본래의 목소리다.
              </span>
            </p>
          </section>
        </div>

        <p className="typewave-footer__legal typewave-mono">
          <span>© 2026 TYPEWAVE — MIT code · all type set in motion</span>
          <span lang="ko">© 2026 타입웨이브 — MIT 코드 · 모든 타이포가 움직인다</span>
        </p>
      </div>
    </footer>
  );
}

"use client";

import { useEffect, useRef } from "react";

/**
 * The lyric ticker. Three marquee bands scroll at crossed speeds and
 * directions: the top band drifts left at resting tempo, the middle band
 * drifts right faster (counterpoint), and the bottom band — the acid one —
 * scrolls left fastest and loudest. Each band's track is duplicated so the
 * `translateX(-50%)` loop is seamless.
 *
 * The marquees are pure CSS (linear transforms on transform-only properties)
 * and self-animate, so there is nothing for a pointer to do — touch-safe by
 * construction. They pause when offscreen (IntersectionObserver toggles an
 * `is-running` class) and stop entirely under reduced motion (the media query
 * cancels the animation, the bands sit static and fully readable).
 *
 * The lyric lines are real bilingual microcopy — fragments of a fictional
 * track — never lorem. Korean is first-class: the middle band leads with
 * Hangul.
 */

type Band = {
  cls: string;
  speed: "l" | "r" | "acid";
  items: { en: string; ko: string }[];
};

const BANDS: Band[] = [
  {
    cls: "typewave-marquee__band--a",
    speed: "l",
    items: [
      { en: "type as the only instrument", ko: "유일한 악기로서의 타이포" },
      { en: "the waveform is a word", ko: "파형은 곧 단어" },
      { en: "stretch until it sings", ko: "노래할 때까지 늘려라" },
      { en: "one accent on pure black", ko: "순흑 위 액센트 하나" },
      { en: "velocity is amplitude", ko: "속도가 진폭이다" },
    ],
  },
  {
    cls: "typewave-marquee__band--b",
    speed: "r",
    items: [
      { en: "every glyph is a sample", ko: "한 글자가 하나의 샘플" },
      { en: "scrub the spectrum", ko: "스펙트럼을 스크럽해라" },
      { en: "narrow to wide, thin to heavy", ko: "좁게에서 넓게, 얇게에서 무겁게" },
      { en: "the page reads like a track", ko: "페이지가 트랙처럼 읽힌다" },
      { en: "hold the letter, hold the note", ko: "글자를 잡아라, 음표를 잡아라" },
    ],
  },
  {
    cls: "typewave-marquee__band--acid",
    speed: "acid",
    items: [
      { en: "TYPEWAVE — 2026", ko: "타입웨이브 — 2026" },
      { en: "acid green at 17.8:1", ko: "산성 초록, 명암비 17.8:1" },
      { en: "variable font wdth 62–125", ko: "가변 폰트 폭 62–125" },
      { en: "scroll is the play head", ko: "스크롤이 재생 머리다" },
    ],
  },
];

export default function MarqueeBands() {
  const rootRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root || !("IntersectionObserver" in window)) return;
    const bands = Array.from(
      root.querySelectorAll<HTMLElement>(".typewave-marquee__band"),
    );
    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          const el = hit.target as HTMLElement;
          el.classList.toggle("is-running", hit.isIntersecting);
        }
      },
      { rootMargin: "60px 0px" },
    );
    for (const b of bands) io.observe(b);
    return () => io.disconnect();
  }, []);

  return (
    <section
      className="typewave-marquee"
      aria-labelledby="typewave-marquee-title"
      ref={rootRef}
    >
      <h2 id="typewave-marquee-title" className="typewave-sr">
        Lyric ticker bands · 가사 티커
      </h2>
      {BANDS.map((band, bi) => (
        <div
          key={band.cls}
          className={`typewave-marquee__band ${band.cls} typewave-mono`}
          aria-hidden="true"
        >
          <div
            className={`typewave-marquee__track typewave-marquee__track--${band.speed}`}
          >
            {/* two copies for a seamless -50% loop */}
            {[0, 1].map((copy) => (
              <ul key={copy} className="typewave-marquee__list">
                {band.items.map((item, i) => (
                  <li key={`${bi}-${copy}-${i}`} className="typewave-marquee__item">
                    <span>{item.en}</span>
                    <span lang="ko">{item.ko}</span>
                    <i className="typewave-marquee__dot" aria-hidden="true" />
                  </li>
                ))}
              </ul>
            ))}
          </div>
        </div>
      ))}
    </section>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import { useScrollProgress } from "../hooks/useScrollProgress";

/**
 * The signature. A 320vh corridor pins a 100svh stage; scroll progress maps
 * the wordmark TYPEWAVE across the full range of Archivo's axes —
 * `font-variation-settings` interpolates 'wdth' 62 → 125 and 'wght' 100 → 900
 * as the corridor scrubs 0 → 1. It is an audio timeline: the wordmark opens
 * thin and narrow at the head, fills out and stretches wide through the
 * body, and slams to its widest/heaviest at the tail — like sweeping a
 * filter across the spectrum.
 *
 * The progress is lerped inside a single rAF (0.14/frame) so the type trails
 * the scroll with mass, never re-rendering React. A Space Mono HUD reports
 * the live `wdth`/`wght` values like a patch readout, and a vertical acid
 * playhead tracks the position with a 2.4s held pulse. An 8-row acid
 * hairline grid sits behind the wordmark as a spectrum baseline.
 *
 * Reduced motion: the wordmark is parked at one composed state (wdth 118,
 * wght 760 — late in the morph), the corridor collapses to normal height,
 * and the HUD shows the parked values. No-JS: same static state, normal
 * flow, fully readable.
 *
 * `enabled` here is `!reduced` — the hook no-ops under reduced motion.
 */
export default function ScrubWordmark() {
  const sectionRef = useRef<HTMLElement | null>(null);
  const wordRef = useRef<HTMLSpanElement | null>(null);
  const wdthRef = useRef<HTMLSpanElement | null>(null);
  const wghtRef = useRef<HTMLSpanElement | null>(null);
  const playheadRef = useRef<HTMLSpanElement | null>(null);
  const targetPRef = useRef(0);
  const reduced = usePrefersReducedMotion();

  // Reduced-motion parked state: a composed late-morph frame. The parked
  // wdth/wght (118/760) is set in styles.css under the reduced-motion media
  // query and as the default .typewave-scrub__word value; JS only drives the
  // morph when motion is allowed. STILL_P selects where on the corridor the
  // reduced HUD reads land.
  const STILL_P = 0.8;

  useScrollProgress(
    sectionRef,
    (p) => {
      targetPRef.current = p;
    },
    !reduced,
  );

  useEffect(() => {
    const section = sectionRef.current;
    const word = wordRef.current;
    if (!section || !word) return;

    let raf = 0;
    let running = false;
    let visible = true;
    let disposed = false;
    let last = 0;
    const shownP = reduced ? STILL_P : 0;

    // map scrub progress → axis values
    const WDTH_MIN = 62;
    const WDTH_MAX = 125;
    const WGHT_MIN = 100;
    const WGHT_MAX = 900;
    const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
    const ease = (t: number) => t * t * (3 - 2 * t); // smoothstep, so the
    // morph's middle travels fastest — like a filter sweep spending the least
    // time at its midpoint

    const apply = (p: number) => {
      const e = ease(p);
      const wdth = lerp(WDTH_MIN, WDTH_MAX, e);
      const wght = lerp(WGHT_MIN, WGHT_MAX, e);
      word.style.fontVariationSettings = `'wdth' ${wdth.toFixed(1)}, 'wght' ${wght.toFixed(0)}`;
      if (wdthRef) wdthRef.current!.textContent = `wdth ${wdth.toFixed(0)}`;
      if (wghtRef) wghtRef.current!.textContent = `wght ${wght.toFixed(0)}`;
      if (playheadRef) {
        playheadRef.current!.style.left = `${(p * 100).toFixed(2)}%`;
        playheadRef.current!.setAttribute(
          "aria-valuenow",
          String(Math.round(p * 100)),
        );
      }
    };

    if (reduced) {
      // corridor collapsed in CSS; nothing to drive. Pin the HUD to the exact
      // parked values the stylesheet paints under reduced motion (wdth 118,
      // wght 760 at 80% of the corridor) so the readout matches the wordmark.
      if (wdthRef.current) wdthRef.current.textContent = "wdth 118";
      if (wghtRef.current) wghtRef.current.textContent = "wght 760";
      if (playheadRef.current) {
        playheadRef.current.style.left = "80%";
        playheadRef.current.setAttribute("aria-valuenow", "80");
      }
      return;
    }

    apply(shownP); // first paint — the morph's head (wdth 62, wght 100)

    let currentP = 0;
    const SCRUB_LERP = 0.14;
    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = dt / 16.7; // frame-rate normalized
      currentP += (targetPRef.current - currentP) * SCRUB_LERP * k;
      if (Math.abs(targetPRef.current - currentP) > 0.0004 || visible) {
        apply(currentP);
      }
    };

    const shouldRun = () => visible && !document.hidden;
    const sync = () => {
      if (disposed) return;
      if (shouldRun()) {
        if (!running) {
          running = true;
          last = performance.now();
          raf = requestAnimationFrame(step);
        }
      } else if (running) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };
    const onVisibility = () => sync();

    const io = new IntersectionObserver(
      (hits) => {
        visible = hits[hits.length - 1].isIntersecting;
        sync();
      },
      { rootMargin: "120px 0px" },
    );
    io.observe(section);
    document.addEventListener("visibilitychange", onVisibility);
    sync();

    return () => {
      disposed = true;
      running = false;
      cancelAnimationFrame(raf);
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [reduced]);

  return (
    <section
      ref={sectionRef}
      className="typewave-scrub"
      aria-labelledby="typewave-scrub-title"
    >
      <div className="typewave-scrub__sticky">
        <header className="typewave-scrub__head">
          <p className="typewave-sechead__no typewave-mono" aria-hidden="true">
            TRACK 02 · SCRUB
          </p>
          <h2 className="typewave-sechead" id="typewave-scrub-title">
            THE MORPH
            <span lang="ko" className="typewave-sechead__ko">
              늘어남
            </span>
          </h2>
          <p className="typewave-scrub__slug">
            Scroll scrubs the wordmark across its full width and weight range
            — a filter sweeping the spectrum.
            <span lang="ko">
              스크롤이 워드마크의 폭과 굵기 전 범위를 스크럽한다 — 스펙트럼을
              쓸고 지나가는 필터.
            </span>
          </p>
        </header>

        <div
          className="typewave-scrub__stage"
          role="img"
          aria-label="The wordmark TYPEWAVE morphing across its variable-font width and weight axes, scrubbed by scroll: narrow and thin at the head, wide and heavy at the tail, like an audio timeline. 스크롤로 스크럽되는 워드마크 TYPEWAVE — 가변 폰트의 폭과 굵기 축을 따라 좁고 얇은 시작에서 넓고 무거운 끝으로 변형된다. 오디오 타임라인처럼."
        >
          {/* spectrum baseline: 8 faint acid hairlines */}
          <div className="typewave-scrub__grid" aria-hidden="true">
            {Array.from({ length: 8 }).map((_, i) => (
              <i key={i} />
            ))}
          </div>

          {/* the timeline playhead, vertical acid, pulsing */}
          <span
            ref={playheadRef}
            className="typewave-scrub__playhead"
            aria-hidden="true"
          />

          {/* the morphing wordmark */}
          <span ref={wordRef} className="typewave-scrub__word">
            TYPEWAVE
          </span>
          <span className="typewave-scrub__wordko" lang="ko">
            타입웨이브
          </span>

          {/* patch readout */}
          <dl className="typewave-scrub__hud typewave-mono" aria-hidden="true">
            <div>
              <dt>axis</dt>
              <dd ref={wdthRef}>wdth 62</dd>
            </div>
            <div>
              <dt>weight</dt>
              <dd ref={wghtRef}>wght 100</dd>
            </div>
            <div>
              <dt>position</dt>
              <dd>0 → 1 · scrub</dd>
            </div>
          </dl>
        </div>

        <p className="typewave-scrub__note">
          Hold anywhere; the type holds with you. The wordmark has no clock of
          its own — only your scroll.
          <span lang="ko">
            멈추면 글자도 함께 멈춘다. 워드마크에는 자기 시계가 없다 — 오직
            당신의 스크롤뿐.
          </span>
        </p>
      </div>
    </section>
  );
}

"use client";

import { Fragment, type CSSProperties } from "react";

/**
 * Accessible split text for the kinetic headlines. The parent element
 * carries the accessible name via `aria-label`; this span is `aria-hidden`
 * and purely visual — one <span> per glyph, each with a `--i` index used by
 * CSS for stagger. Words are wrapped in nowrap spans separated by real
 * spaces, so a headline can break between words on a narrow screen but
 * never inside one.
 *
 * The entrance animation is opt-in: it only runs under `.typewave-js` when
 * an ancestor carries `.is-on`, so without JavaScript the headline simply
 * stands at its resting state — fully readable, fully styled.
 */
export default function SplitText({ text }: { text: string }) {
  const words = text.split(" ");
  const offsets: number[] = [];
  let acc = 0;
  for (const word of words) {
    offsets.push(acc);
    acc += word.length;
  }

  return (
    <span className="typewave-split" aria-hidden="true">
      {words.map((word, w) => (
        <Fragment key={`${w}-${word}`}>
          {w > 0 ? " " : null}
          <span className="typewave-split__word">
            {Array.from(word).map((ch, c) => (
              <span
                key={`${offsets[w] + c}-${ch}`}
                className="typewave-split__ch"
                style={{ "--i": offsets[w] + c } as CSSProperties}
              >
                {ch}
              </span>
            ))}
          </span>
        </Fragment>
      ))}
    </span>
  );
}

